const verificationEscape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function verificationMarkup({project,reports,sourceHash,busy,selectedId,online}){
 const esc=verificationEscape,own=reports.filter(r=>r.projectId===project.id),report=own.find(r=>r.id===selectedId)||own[0];
 const rows=items=>items.map(c=>`<div class="history-item"><div><strong>${esc(c.name||c.file||c.mode)} <span class="badge ${c.status==='warn'?'warning':''}">${esc(c.status)}</span></strong><p>${esc(c.message||((c.required?'Required':'Optional')+' / '+(c.completed?new Date(c.completed).toLocaleString():'No matching execution recorded.')))}</p></div></div>`).join('');
 return `<div class="notice">Reports describe a particular source snapshot. They are not a production-readiness or security certificate. Browser results are reported by the preview; project code can influence them. Verification uses zero AI tokens.</div><section class="panel settings-card"><h2>${esc(project.name)}</h2><p>Run static analysis, inspect fixture definitions, then run preview checks. React builds and Node tests remain explicit actions in Runtime.</p><div class="settings-buttons"><button class="btn primary" data-action="verify-create" ${busy||!online?'disabled':''}>${busy?'Checking source...':'Verify current source'}</button><button class="btn secondary" data-action="verify-refresh" ${busy||!online?'disabled':''}>Refresh reports</button><button class="btn secondary" data-action="verify-preview">Open preview checks</button><button class="btn secondary" data-view="runtime">Open Runtime</button></div>${!online?'<p>Start the laptop server and sign in to save verification reports.</p>':''}</section>${report?`<div class="section-heading"><h2>Selected verification report</h2><button class="text-button" data-report-action="download" data-report-id="${esc(report.id)}">Download report JSON</button></div><section class="panel settings-card"><h2>${report.sourceHash===sourceHash?'Matches current source':'Source changed — verification is out of date'}</h2><p><span class="badge ${report.status==='needs-attention'?'warning':''}">${esc(report.status)}</span> / ${new Date(report.created).toLocaleString()} / ${report.fileCount} files</p><p>Source fingerprint: <code>${esc(report.sourceHash)}</code></p>${report.sourceHash!==sourceHash?'<p>Run Verify current source before using this report to assess your edits.</p>':''}<h3>Static analysis</h3>${rows(report.staticChecks)}<h3>Browser fixture definitions</h3>${rows(report.fixtures)}<h3>Container execution for this source</h3>${rows(report.execution)}<h3>Preview results / browser-reported</h3><p>${esc(report.browser.status)}${report.browser.mode?' / '+esc(report.browser.mode)+' preview':''}. ${report.browser.status==='not-run'?'Open Preview, wait until ready, then choose Run browser checks.':'These results are supplied by the sandbox, not independently certified.'}</p>${rows(report.browser.checks)}</section>`:'<section class="panel"><div class="empty">No report for this project yet. Verify current source to create one.</div></section>'}<div class="section-heading"><h2>Report history</h2></div><section class="panel">${own.length?own.map(r=>`<div class="history-item"><div><strong>${esc(r.projectName)} / ${esc(r.status)}</strong><p>${new Date(r.created).toLocaleString()} / ${esc(r.sourceHash.slice(0,12))}</p></div><button class="btn secondary" data-report-action="select" data-report-id="${esc(r.id)}">View report</button></div>`).join(''):'<div class="empty">Up to 20 reports per project are retained on this laptop.</div>'}</section>`;
}
